mapper.select:
SELECT  FROM interview_event e
WHERE e.owner_id=#{owner} AND e.start_at < #{to} AND e.end_at > #{from}
AND e.target_id=#{targetId}
AND e.status=#{status}

  AND (e.start_at > #{cursorTime} OR (e.start_at=#{cursorTime} AND e.id > #{cursorId}))

ORDER BY e.start_at,e.id LIMIT #{limit}

SELECT  FROM interview_event e
WHERE e.owner_id=#{owner} AND e.status='PLANNED' AND e.reminder_acknowledged_at IS NULL AND e.remind_at <= #{asOf}

  AND (e.remind_at > #{cursorTime} OR (e.remind_at=#{cursorTime} AND e.id > #{cursorId}))

ORDER BY e.remind_at,e.id LIMIT #{limit}

SELECT revision,action,title,start_at,status,reason,created_at FROM interview_event_history
WHERE owner_id=#{owner} AND event_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}
